<?php require_once '../includes/auth.php';admin_required();$statuses=['pending','flagged','approved','rejected'];$status=$_GET['status']??'pending';if(!in_array($status,$statuses,true))$status='pending';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';$note=trim($_POST['note']??'');if(in_array($action,['approved','rejected','flagged'],true)&&$id){if(in_array($action,['rejected','flagged'],true)&&$note==='')$error='A moderation note is required for rejected or flagged products.';else{$q=$pdo->prepare('UPDATE products SET moderation_status=?,moderation_note=?,moderated_by=?,moderated_at=NOW() WHERE id=?');$q->execute([$action,$note,$_SESSION['user_id'],$id]);audit_log('product_'.$action,'product',$id,$note);go('/admin/products.php?status='.urlencode($action));}}}$q=$pdo->prepare("SELECT p.*,s.name AS store_name,u.name AS seller_name FROM products p JOIN stores s ON s.id=p.store_id JOIN users u ON u.id=s.user_id WHERE p.moderation_status=? ORDER BY p.created_at DESC");$q->execute([$status]);$ps=$q->fetchAll();$title='Product moderation';require '../includes/header.php';?><h1>Product moderation</h1><div class="mb-3"><?php foreach($statuses as $x):?><a class="btn btn-sm <?= $x===$status?'btn-success':'btn-outline-success'?> me-1" href="/admin/products.php?status=<?=e($x)?>"><?=e(ucfirst($x))?></a><?php endforeach;?></div><?php if(!empty($error)):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><?php foreach($ps as $p):?><div class="card mb-3"><div class="card-body"><?php if($p['image']):?><img src="/uploads/<?=e($p['image'])?>" alt="<?=e($p['name'])?>" style="width:120px;height:120px;object-fit:cover" class="rounded mb-2"><?php endif;?><h5><?=e($p['name'])?></h5><p class="mb-1"><?=e($p['store_name'])?> · seller: <?=e($p['seller_name'])?></p><p><?=e($p['category'])?> · <?=money($p['price'])?></p><?php if(!empty($p['description'])):?><p><?=e($p['description'])?></p><?php endif;?><?php if(!empty($p['moderation_note'])):?><div class="alert alert-secondary"><?=e($p['moderation_note'])?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=e($p['id'])?>"><textarea class="form-control mb-2" name="note" placeholder="Moderation note"><?=e($p['moderation_note']??'')?></textarea><button class="btn btn-success" name="action" value="approved">Approve</button> <button class="btn btn-outline-warning" name="action" value="flagged">Flag</button> <button class="btn btn-outline-danger" name="action" value="rejected">Reject</button></form></div></div><?php endforeach;?><?php if(!$ps):?><p>No products in this queue.</p><?php endif;?><?php require '../includes/footer.php';?>